fn bin_search(a: &[i32], k: i32) -> bool {
    let mut lo = 0;
    let mut hi = a.len();

    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if a[mid] == k {
            return true;
        } else if a[mid] < k {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }

    false
}

